Test:  user sees the whole catalogue once it has loaded
File:  cart.spec.js

Error: expect(received).toBe(expected) // Object.is equality

Expected: 5
Received: 4

  68 |     // Assert — all five products are listed
  69 |     const count = await shop.products.count();
> 70 |     expect(count).toBe(5);
     |                   ^
  71 |   });
